def S(*ids):return ['b2-east-'+x for x in ids]
def dim(state,k,status,summary,*sids):spec.setdefault(state,{})[k]=dict(status=status,summary=summary,sourceIds=S(*sids))
def rule(key,state,title,req,sids,trigger,deadline=None,exceptions='Applicability and any exclusion must be established from the actual relationship and relevant facts.',topic='sales-disclosure',status='verified',fee=None,renewal=None,limits=None,legal='effective'):
 rid='b2-east-'+key;rules.append(dict(id=rid,title=title,topic=topic,jurisdiction=state,activity='U.S. business-model expansion and partner operations',affectedParty='Brand owner, proposed selling entity and responsible management role',applicability='Only where the cited state provision covers the parties, location, activity and relationship. Federal analysis remains separate.',requirement=req,exceptions=exceptions,trigger=trigger,deadline=deadline,fee=fee,renewal=renewal,dependencies=['Relationship factsheet','Entity and jurisdiction map','Actual source/current-version review'],evidence=['Dated applicability memorandum','Reviewed agreement, disclosure and campaign versions','Named responsible person and evidence dates'],sourceIds=S(*sids),status=status,legalStatus=legal,verifiedAt=DATE if status=='verified' else None,nextReview='2026-12-12',conflicts=[],interpretationLimits=limits or ['Narrow stated issue only; no complete state, sector, employment, tax or local clearance.'],dependentPaths=[],reviewerStatus=REVIEW));return rid

def sec(h,*ps,bullets=None,table=None,sources=None):
 x=dict(heading=h,paragraphs=list(ps))
 if bullets:x['bullets']=bullets
 if table:x['table']=table
 if sources:x['sourceIds']=S(*sources)
 return x
def guide(state,title,desc,rulekeys,sections,output,topic='sales-disclosure',status='published',limits=None):
 slug=state.lower().replace(' ','-');path='/states/'+slug+'/';ids=['b2-east-'+x for x in rulekeys];rr=[r for r in rules if r['id'] in ids];sourceids=sorted({x for r in rr for x in r['sourceIds']}|{x for s in sections for x in s.get('sourceIds',[])})
 for r in rr:r['dependentPaths'].append(path)
 for s in sections:
  if 'sourceIds' not in s:s['sourceIds']=sourceids
 guides.append(dict(id='b2-east-guide-'+slug,path=path,title=title,description=desc,family='state',topic=topic,jurisdictions=[state],status=status,lastReviewed=DATE if status=='published' else None,reviewStatus=REVIEW if status=='published' else 'Research reviewed; material current-law gap remains',readMinutes=max(3,round(sum(len(' '.join(s['paragraphs']+s.get('bullets',[])).split()) for s in sections)/180)),ruleIds=ids,sections=sections,sourceIds=sourceids,nextStage=5 if topic in ['employment','corporate-tax','premises-opening'] else 1,practicalOutput=output,limitations=limits or ['This page addresses its named decision, not a complete state legal survey. Unknown dimensions remain unresolved in the coverage register.','Model classification, state connections, sector-dealer laws, local requirements and the actual transaction need independent review. No sale, exemption, worker status or contract term is approved.']))
rule('al-operation-days','Alabama','Alabama religious-day operating requirements and exceptions','Act2026-591 effectiveJune1,2026 restricts specified religious-day operating requirements after a franchisee assertion, with exceptions for conspicuous existing/original terms, agreement through renewal/amendment and additional-location agreements. Assess the defined parties and exception facts before enforcing or changing operating days.',['al-2026','al-status'],'Setting operating days, amending terms, renewal or expansion',status='conditional',topic='relationship',limits=['Definitions refer to specified product/licensing relationships and exclude listed regulated sectors; application to a particular B2Bservice model is unresolved.','No assertion that all franchisees may close on any chosen day. No comprehensive later-injunction search performed.'])
rule('ak-business-opportunity','Alaska','Alaska covered business-opportunity disclosure and contract duties','Department of Law explains that covered sellers provide disclosure at least10days before a contract or payment and use a written purchase contract describing services, costs, delivery and cancellation terms. Its page separately points to statutory exemptions; those conditions were not fully retrieved in this batch.',['ak-bizopp'],'Covered business-opportunity offer leading to agreement/payment','Agency explanation: at least10days before contract/payment',status='conditional')
rule('ak-process','Alaska','Alaska registration process and dated application','Department of Law’s linked application describes registration at least30days before conducting covered business and calls for promotional materials. The form version is2005; establish the current statutory exemption and process before treating this as a transaction-specific deadline.',['ak-app','ak-bizopp'],'Preparing a covered business-opportunity campaign',status='conditional',renewal='Application supports initial/renewal filings; current renewal terms not independently reconciled.')
rule('az-exclusion','Arizona','Arizona business-opportunity definition excludes federal-rule franchises','ARS44-1271(1)(c)(iii) excludes a franchise as defined in16CFR436.1 from its business-opportunity definition. Establish that definition independently; choosing a licence label is not the test. This exclusion is not absence of every state or sector duty.',['az-definition'],'Classifying the offer and evaluating state business-opportunity coverage')
rule('az-seller','Arizona','Arizona covered seller registration, disclosure and materials','Covered sellers under44-1272register before soliciting from Arizona or a consumer in Arizona; the registration expiresJune30and new/revised sales material is submitted before use. Under44-1276.01a covered registered business-opportunity seller supplies disclosure at least five business days before the earlier stated commitment/payment events.',['az-registration','az-disclosure','az-definition'],'Covered solicitation, changed sales material or consumer commitment','Before covered solicitation/material use; disclosure at least5business days before specified earlier event',status='conditional',renewal='Registration expiresJune30; review annual and supplemental filing requirements.')
rule('ar-applicability','Arkansas','Arkansas Act847 relationship applicability is separate from federal disclosure','Enacted2023Act847amended state relationship-law applicability and removed the prior textual reference to federal Franchise Rule coverage as an exclusion. It also added agreement protections with temporal conditions. Classify the actual Arkansas place-of-business relationship and agreement date rather than treating an FDD as a relationship-law exemption.',['ar-2023'],'Drafting, transfer, renewal or termination of an Arkansas relationship',status='conditional',topic='relationship')
rule('ar-failed-proposal','Arkansas','Arkansas HB1177of2025was not enacted','The official legislative record states that HB1177died in House committee at sine-die adjournment. Do not apply that proposal as an amendment to the operating law.',['ar-2025'],'Reviewing source changes and proposed amendments',legal='not-enacted')
rule('co-worker-covenants','Colorado','Colorado worker restrictive covenants need an independent review','Colorado2026section8-2-113generally voids worker noncompetes restricting compensation for labor unless a stated exception applies. Trade-secret/compensation conditions, scope and separate notice requirements matter. This worker analysis is distinct from an entity-level franchise covenant.',['co-2026labor','co-downloads'],'Recruiting or imposing restrictions on a Colorado worker','For covered permissible covenants: prospective-worker notice before acceptance; current-worker notice at least14days before specified earlier event',status='conditional',topic='employment',limits=['No current compensation dollar threshold is supplied; check applicable threshold and dates.','Do not assume the worker statute decides enforceability of every franchise agreement or owner covenant.'])
rule('ct-mark-exclusion','Connecticut','Connecticut trademark-exclusion claim needs ownership and sublicense evidence','Current FormCT-BOIA-EXeffectiveSeptember30,2025describes a marketing-program claim tied to a federally registered trademark/service mark. It asks who holds the mark and whether assignment/licensing permits sublicensing. The form says posting a claim is not approval or validation.',['ct-form','ct-guidelines'],'Before relying on a trademark-based exclusion from business-opportunity registration',status='conditional',limits=['Current form and older guideline differ in how supporting documents/process are described. Confirm the current channel and requested attachments.','This concerns the cited exclusion; other definitional triggers, disclosure, fraud and sector requirements remain separate.'])
rule('de-distributors','Delaware','Delaware Franchise Security Law has a defined distributor scope','Sections2551–2555define particular franchised-distributor/product relationships and regulate unjust termination/nonrenewal and notice. Tangible-product and in-state place-of-business facts matter; a generic service licence is not automatically within that definition. For covered franchises2555states at least90daysnotice notwithstanding contrary contract terms.',['de-law'],'Distributor agreement drafting, nonrenewal or termination','For covered2555termination/nonrenewal: at least90daysnotice',status='conditional',topic='relationship',limits=['Good cause/bad faith, defined distributors and other applicable statutes must be analysed.','Section2554worker language is limited to purposes of Title19Chapter11; no blanket worker-classification exemption is inferred.'])
rule('fl-annual-notice','Florida','Florida annual franchise exemption notice comes before the covered offer','2026section559.802exempts qualifying federal-definition franchises from PartVIIif, before offering or selling a franchise located in Florida or to a Florida resident, the franchisor files the notice of substantialFTCcompliance and pays the set fee. The exemption lasts one year from filing and may be annually renewed.',['fl-statute','fl-agency'],'Before first covered Florida offer/sale and each exemption anniversary','Before covered offer/sale; renew annually',renewal='One year from notice filing; annual renewal.',limits=['Statute permits a fee not exceeding$100; current actual agency fee was not established from accessible packet. No payable fee amount is invented.','Exemption applicability is not a website clearance or approval of earnings claims.'])
rule('ga-source-version','Georgia','Georgia agency statutory page has an explicit2006currency limit','The agency-hosted statutory page says its text is current through the2006Regular Session. Access today does not verify that its numerical thresholds, exceptions or timing remain current in2026. Obtain current statutory text before relying on the historical business-opportunity provisions.',['ga-agency'],'Reviewing Georgia business-opportunity applicability and editorial source freshness',status='verified',legal='historical',limits=['This rule records a source-version limitation; it does not state current Georgia legal obligations.'])
rule('ga-name-mark','Georgia','Georgia trade-name and mark records answer different questions','The Georgia Secretary of State FAQ distinguishes a trade name identifying a business from a trademark/service mark identifying goods/services. Catalogue the mark owner, registration jurisdiction, goods/services and the selling entity’s licence rights separately from the business-name record.',['ga-mark'],'Preparing an ownership and brand-rights evidence chain',topic='ip-data')
rule('id-operating-records','Idaho','Idaho distinguishes entity registration from licences and local permits','Idaho’s official business portal states that business registration is not a licence and that city/county, occupational and tax requirements can apply separately. Use the actual service and location to contact the responsible agencies; the portal disclaims completeness.',['id-agency'],'Selecting the operating entity, service and actual Idaho location',topic='premises-opening',status='conditional',limits=['The portal statement that Idaho has no general state business licence does not establish absence of franchise, sector, tax or local duties.','Do not rely solely on an absent activity in the online Business Wizard.'])
rule('id-representations','Idaho','Idaho general unfair/deceptive practices remain a separate review','The Attorney General describes the Consumer Protection Act as prohibiting commercial unfair competition and unfair/deceptive practices in trade and commerce. Assess the actual claim, transaction and parties rather than treating any missing specialised filing as a claim-substantiation exemption.',['id-consumer'],'Drafting partner marketing and support/cost representations',status='conditional',limits=['The page is general guidance; particularB2Bcoverage and remedies need statutory/current-case review.'])
rule('ia-business-opportunity','Iowa','Iowa franchise disclosure exemption and service-of-process filing are distinct','2026Chapter551Aincludes independent definitions/exclusions. Its franchise route in551A.4exempts section551A.3subject to timely specified disclosure at the earlier first personal meeting or14daysbefore commitment/payment. Section551A.7separately requires a consent to service before contract/sale; an exemption only from551A.3does not itself remove that filing.',['ia-bizopp'],'Covered offer, first personal meeting, contract or sale','Selected franchise route: earlier first personal meeting or14daysbefore stated earlier commitment/payment; consent before contract/sale',status='conditional',limits=['Section551A.1(2)(b)(3)registered-mark/net-worth exclusion is different from the551A.4franchise disclosure exemption.','Establish the actual chapter scope and route; no universal filing conclusion.'])
rule('ia-current-relationship','Iowa','Iowa new-agreement relationship review uses537A.10','2026section537A.10covers defined Iowa-operated franchises with agreements entered into on/afterJuly1,2000, with stated exclusions and location conditions. It contains transfer, encroachment, termination and other protections. Chapter523Hhas an express limitation for agreements entered on/afterthat date.',['ia-currentrelationship','ia-franchise'],'New agreement, transfer, territory allocation, termination or renewal',status='conditional',topic='relationship')
rule('ia-future-review','Iowa','Iowa signed2027amendment is a future review task','The official2026amendment table records a signed amendment to537A.10(7)(c)(2), SF2497sections29and32, effectiveJanuary1,2027. Flag the dependent termination guide and template for review; do not treat the future provision as already effective onNovember12,2026.',['ia-amendments'],'Editorial review beforeJanuary1,2027','Review before2027-01-01',legal='enacted-not-effective')
rule('ks-foreign-qualification','Kansas','Kansas foreign qualification is an entity activity analysis','KansasSOSstates that non-Kansas businesses doing business in Kansas must register and provides foreign-entity application forms. Determine the entity and its actual Kansas activities and exceptions; a resident-agent/registered-office task is not a franchise-offer permission.',['ks-sos','ks-register'],'Determining whether a non-Kansas group entity will do business in Kansas',status='conditional',topic='corporate-tax',limits=['No automatic recommendation to incorporate locally or move the home headquarters.','Detailed doing-business exceptions, tax treatment and sales/franchise requirements remain independent.'])
rule('ky-franchise-notice','Kentucky','Kentucky franchise exemption requires notice and current portal evidence','KRS367.807(1)(a)links its franchise exemption to the federal definition/compliance and written notice. Current40KAR12:410effectiveJune30,2026specifies the Franchise Exemption Notice portal, authority-to-transact evidence and a copy of theFDDfor this route.',['ky-exemption','ky-rules'],'Claiming the Kentucky franchise exemption',status='conditional',limits=['Confirm federal compliance and exact exemption applicability; portal submission does not certify the model.'])
rule('ky-material-changes','Kentucky','Kentucky exemption notice does not end recordkeeping','Current40KAR12:410section4requires a registered seller and an offeror submitting an exemption notice to give written notification within14days of a material change to the supplied information; section5addresses responsive records.',['ky-rules'],'Material change after registration or exemption submission','Within14days of material change',status='verified')
rule('ky-nonexempt','Kentucky','Kentucky covered non-exempt sellers use a separate registration track','Current40KAR12:410requires approval before covered sales to Kentucky residents, electronic registration/renewal and specified supporting documents. That non-exempt track is different from the franchise exemption notice and has its own fees, annual period and material-change records.',['ky-rules'],'A covered business-opportunity seller without an established exemption','Approval before covered sales',status='conditional',renewal='Approved registration/renewal valid one year from written confirmation.')
rule('la-definition','Louisiana','Louisiana mark-related exception is tied to a specified trigger','RS51:1821(1)(d)contains registered-mark language for the described sales/marketing-plan provision. Other location, buyback and earnings/refund triggers in1(a)–(c)must be independently examined. Do not describe the mark as a universal business-opportunity exemption.',['la-definition'],'Designing support, location assistance, earnings/refund promises and payments',status='conditional')
rule('la-bonds','Louisiana','Louisiana specified business opportunities have separate seller and agent bonds','RS51:1822requires covered seller/agent bonds filed before business including advertising/soliciting. Seller and agent amounts differ. SubsectionGlimits these bond duties to opportunities defined in51:1821(1)(a),(b)or(c), so do not apply the bond automatically to every marketing-plan model.',['la-registration','la-definition'],'Advertising/soliciting a business opportunity within the identified bond scope','File covered bonds before business including advertising or soliciting',status='conditional')
rule('la-claims','Louisiana','Louisiana covered business-opportunity claims need substantiation and written promises','RS51:1823addresses documented earnings support, specified advertising disclosures, actual seller identification, written agreement promises and appointment of the secretary of state for service of process. Use actual representations and statutory coverage, not the label on the contract.',['la-prohibitions','la-definition'],'Preparing covered advertisements, promises and contracts',status='conditional')
rule('la-real-estate','Louisiana','Louisiana real-estate franchise representative is a sector condition','RS37:1465prohibits a franchisor from entering a franchise agreement with a real-estate broker in Louisiana without appointing a Louisiana-licensed real-estate broker as its representative in the state. A brand licence does not displace professional-sector rules.',['la-realestate'],'Entering the described real-estate broker franchise agreement','Before entering the described agreement',status='conditional',topic='premises-opening')
rule('me-opportunities','Maine','Maine covered business opportunities have early promotional and disclosure events','Under current Title32Chapter69-B, covered sellers register before selling, offering, advertising or promotion. Section4692requires disclosure at the earliest specified72-hour preagreement/prepayment point or the first face-to-face sales meeting. The registered-mark language in4691qualifies the marketing-program limb; other triggers remain separate.',['me-law'],'Covered advertising/promotion, first face-to-face meeting, agreement or payment','Registration before promotion; disclosure at earliest specified meeting/72-hour event',status='conditional')
rule('me-contract-cancellation','Maine','Maine disclosure and avoidance affect the launch calendar','For a covered business opportunity,4698permits written avoidance within three full business days following contract day and sets return-of-goods/funds provisions. Sections4695–4697cover financial security, registration and renewal with exceptions. Record those obligations independently of the federal franchise disclosure clock.',['me-law'],'Covered agreement and timely avoidance; opening-fund commitments',status='conditional')
rule('ma-services','Massachusetts','Massachusetts service work requires an independent classification analysis','General Laws149section148B(a)starts with an individual performing services and requires all three stated conditions for its independent-contractor exception: freedom from control in contract/fact, service outside the employer’s usual course and an independently established business of the same nature. A franchise label does not itself answer whose services are performed for whom.',['ma-classification'],'Allocating actual service delivery and contracting with individuals',status='conditional',topic='employment',limits=['Statutory services threshold and relevant case law must be applied to actual facts; this is not a determination that every franchisee is an employee.','Separate employee, operator-entity and franchisor responsibilities; other tests and taxes remain independent.'])
rule('ms-historical-notice','Mississippi','Mississippi notice-law research retains an explicit currency gap','Enacted2018SB2805(chapter394)preserved franchise notice language and exceptions in75-24-53. Its official status is Law, effectiveJuly1,2018. Current2026consolidation and any later amendments/cases were not obtained; do not use the historical notice text as automatic permission for a current termination.',['ms-2018','ms-status'],'Researching a Mississippi relationship termination or nonrenewal',status='unresolved',topic='relationship',legal='historical',limits=['Current official consolidated code/source reconciliation remains blocked; later primary case-law review is still needed.'])
rule('mo-notice','Missouri','Missouri franchise exit notice depends on state definition and exceptions','Current407.400defines the covered relationship including community-of-interest and place-of-business conditions. For a covered franchise407.405requires90dayswritten notice of cancellation/termination/nonrenewal, with specific misconduct, abandonment, insolvency and bad-check exceptions. Establish any exception from evidence.',['mo-definition','mo-relationship'],'Covered termination, cancellation or nonrenewal','Generally at least90dayswritten notice; statutory exceptions require review',status='conditional',topic='relationship')
rule('mo-business-opportunity','Missouri','Missouri business-opportunity representations are a separate screen','409.1000sets its own business-opportunity definition and exclusions;409.1003prohibits misrepresentations about investment, support, profits and contract rights and assigning the same so-called exclusive territory to multiple purchasers. Assess both the facts and representations independently from407.400relationship coverage.',['mo-bizopp','mo-prohibitions'],'Partner recruitment, territory design and support representations',status='conditional')
guide('Alabama','Alabama: check operating-day terms before changing the franchise','Alabama’s 2026 religious-day operating law has explicit exceptions; map the agreement history and covered parties.',['al-operation-days'],[
sec('The operating-days question has a state layer','Alabama’s enrolled SB138 text sets June1,2026 as its effective date. The official fiscal note identifies it as enacted Act2026-591. It restricts specified religious-day operating requirements when a defined franchisee asserts a sincerely held religious belief, but it also contains express exceptions. This is not a blanket right to disregard every operating-days obligation.'),
sec('Read the exception facts','The text treats conspicuous terms in the original or then-existing agreement, an agreed renewal/amendment and an agreement expanding the number of locations separately. The definitions and listed regulated-sector exclusions also matter. Whether a particular service model falls within the defined parties requires review; a federal franchise analysis does not answer that state scope question.'),
sec('Fictional example: a branded service network','A UK brand wants every operator to offer weekend response. Before adding an operating-days rule, its COO collects the signed agreement, incorporated operating documents, their dates, the proposed amendment and any religious-day assertion. The team should examine alternatives for customer coverage while the actual statutory scope and exception are reviewed. This exercise does not decide the exception or require collection of sensitive belief evidence through this site.'),
sec('Create an agreement-history record',bullets=['Which entity is the franchisor and who is the franchisee under the relevant definition?','Which document currently contains the operating requirement, and how conspicuous is it?','Is this an original agreement, amendment, renewal or added-location agreement?','What service-level commitment needs operational coverage?','Who will review the scope, exceptions and proposed response before enforcement?'])], 'An operating-days decision record with agreement versions and a named review owner.',topic='relationship')
guide('Alaska','Alaska: screen the business-opportunity rules before a partner campaign','Alaska’s business-opportunity process is a separate workstream; establish any exemption before relying on franchise terminology.',['ak-business-opportunity','ak-process'],[
sec('Start with the offer and promised assistance','Alaska Department of Law describes business opportunities involving products, equipment, supplies or services to start a business, coupled with particular assistance or representations. Its guidance identifies registration, security, disclosure and written-contract requirements for covered sellers and separately directs readers to statutory exemptions. A model labelled a licence is not automatically outside that workstream.'),
sec('Plan the evidence before the sales event','The agency explains disclosure at least ten days before contract or payment and a written agreement describing costs, promised services, delivery and cancellation. Its linked application describes registration preparation and promotional-material attachments. That application is marked Version2/9/05, so the current statutory exemption and form/process must be reconciled before a team fixes an actual offer date.'),
sec('Fictional example: a Danish equipment-supported service','The brand supplies specialist machines and promises help obtaining locations. Its manager records the exact goods, payments, location assistance, earnings statements and potential Alaska prospect connections. The team establishes the applicable route before scheduling a paid partner launch. The source does not prove that every such arrangement is covered or exempt.'),
sec('Prepare a classification packet',bullets=['Full relationship factsheet, including promised locations or buybacks.','Every payment and commitment with timing.','Proposed advertisement, script, agreements and support description.','Written statutory exemption analysis or applicable filing task.','Current application/process confirmation and named responsible person.'])], 'An Alaska business-opportunity screen and source-version check before promotion.')
guide('Arizona','Arizona: test the specific franchise exclusion before using the sales rules','Arizona’s business-opportunity definition excludes federal-rule franchises; other offers can follow a separate registration and disclosure track.',['az-exclusion','az-seller'],[
sec('A definition exclusion is a narrow answer','ARS44-1271(1)(c)(iii) excludes a franchise defined by16CFR436.1 from this business-opportunity definition. That requires an actual federal-definition analysis. It is different from assuming that a contract called a licence is unregulated, and it does not establish an absence of Arizona sector, consumer or operating duties.'),
sec('A different track can have earlier tasks','For covered sellers,44-1272requires registration before solicitation from Arizona or of a consumer located there, sets a June30expiry and requires new/revised solicitation materials before use. Section44-1276.01 sets a five-business-day disclosure period for specified covered business-opportunity commitments or payment events. These statements describe that track; they are not additional duties imposed automatically on every excluded franchise.'),
sec('Fictional example: a Finnish technical-services package','The seller provides equipment, training and a marketing system and projects that customers will earn more than their initial payment. The expansion director records the actual payments, assistance, brand association and representations. A reviewer then compares the federal franchise definition and Arizona’s separate business-opportunity scope. Neither a low initial fee nor a licence heading alone settles the result.'),
sec('Keep the outputs separate',table={'headers':['Question','Useful evidence'],'rows':[['Federal definition','Trademark, assistance/control and payments facts'],['Arizona business-opportunity scope','Exact representations and statutory exclusion analysis'],['Covered-seller process','Campaign location, registration/effectiveness, materials and dates'],['Other state duties','Sector, customer and actual operating-location questions']]} )], 'A model classification memo that records the Arizona exclusion separately from any covered-seller calendar.')
guide('Arkansas','Arkansas: federal disclosure does not settle relationship-law coverage','Use enacted Act847of2023 and the actual agreement history; a 2025 applicability proposal died in committee.',['ar-applicability','ar-failed-proposal'],[
sec('Separate the enacted amendment from the proposal','Enacted Act847of2023 amended Arkansas Franchise Practices Act applicability and added relationship provisions. In the official PDF, the prior reference to federal Franchise Rule coverage is struck from the exclusion text. The legislature’s official record says HB1177of2025 died in House committee at sine-die adjournment. That proposed bill is not an operative amendment.'),
sec('Map place, dates and exclusions','The enacted text addresses a franchise whose performance contemplates or requires a place of business in Arkansas. It also has stated exclusions and distinguishes retroactive applicability amendments from provisions applying to agreements entered or renewed after the Act’s effective date. An FDD and a contract choice-of-law clause are not a substitute for that state analysis.'),
sec('Fictional example: a Dutch maintenance operator','The brand wants to change its Arkansas operator’s transfer and exit terms. The company secretary collects the original agreement, renewals, transfers, guarantees and the actual place of business. The COO separately records service obligations and alleged performance issues. The reviewer can then identify the applicable version and provisions before the team relies on a new term or a home-market termination clause.'),
sec('A practical source-control check',bullets=['Keep the enacted Act PDF and reviewed marked-text interpretation.','Mark the failed2025proposal as not enacted.','Record the original, renewal and transfer dates.','Identify each claimed statutory exclusion and its facts.','Assign current consolidated-code, effective-date and relevant case-law reconciliation before a transaction-specific decision.'])], 'An Arkansas agreement chronology and enacted-versus-proposed source record.',topic='relationship')
guide('Colorado','Colorado: review manager restrictions separately from brand rights','A Colorado worker noncompete has its own scope, exception and notice analysis; it is not answered by a franchise clause.',['co-worker-covenants'],[
sec('Identify who is being restricted','The2026Colorado statute8-2-113addresses covenants restricting an individual’s compensation for labor. Its general prohibition has stated exceptions, including conditions involving compensation, trade secrets and scope, as well as other defined categories. A manager’s employment restriction and an operator entity’s brand agreement are different documents and need separate analysis.'),
sec('Notice is a real preparation task','For otherwise permissible covered covenants, the statute requires notice and the terms before a prospective worker accepts employment. It separately specifies a current-worker period and a clear, conspicuous, signed notice in a separate document. Meeting a notice step alone does not establish that the restriction qualifies for an exception.'),
sec('Fictional example: a Singapore facilities brand','A U.S. partner recruits a Colorado general manager. The home-market template combines confidentiality, customer restrictions and a broad noncompete in the franchise manual. The hiring team identifies the actual employer, worker, protected information, compensation period and intended restriction. It prepares an employment-specific review rather than assuming that the brand’s desire for consistency makes every restriction enforceable.'),
sec('What the team should record',bullets=['Worker versus operator entity; actual employer and work location.','Restriction type, scope, dates and claimed legitimate interest.','Applicable current compensation threshold, if the selected exception uses one.','Required notice, language, separate document and signature evidence.','Independent review of franchise-owner covenants and other applicable law.'])], 'A Colorado worker-restriction review sheet prepared before the hiring commitment.',topic='employment')
guide('Connecticut','Connecticut: trace the registered mark through to the selling entity','The current trademark-exclusion claim asks who owns the mark and whether the seller can sublicense it; posting is not approval.',['ct-mark-exclusion'],[
sec('The current form asks a group-structure question','FormCT-BOIA-EX, effective September30,2025, describes a marketing-program exclusion claim involving a federally registered trademark or service mark. It asks whether the seller holds the mark, whether it has been assigned and whether the owner has licensed use and sublicensing to franchisees or purchasers. An overseas parent’s registration certificate alone may not show the selling subsidiary’s rights.'),
sec('A filed claim is not validation','The form expressly says that the Department posts claims but cannot approve or validate them and that the seller bears the burden. The Department’s older guideline discusses certificates and supporting assignments/licences. Confirm the current filing route and requested evidence using the current form and agency directions; do not silently treat the older wording as the latest process.'),
sec('Fictional example: a Malaysian parent and U.S. seller','The parent owns the brand, a Singapore group company has a regional licence and a new U.S. subsidiary will sell partner rights. The company secretary draws the chain of ownership, licensing territory and sublicense permission. Missing U.S. authority remains an unresolved document task; group ownership alone does not fill the gap.'),
sec('Build a mark-rights packet',bullets=['Federal registration identity, owner, relevant goods/services and status.','Exact entity proposing the Connecticut offer.','Signed assignment/licence chain and sublicense authority.','Reviewed exclusion grounds and any other definitional trigger.','Current filed claim, supporting evidence and responsible signatory.'])], 'A Connecticut mark-ownership and sublicense diagram with a documented claim review.')
guide('Delaware','Delaware: a distributor relationship can change exit rights','The Franchise Security Law defines particular distributor relationships; check that scope before using a termination clause.',['de-distributors'],[
sec('Start with the defined distributor','Delaware’s Title6Chapter25SubchapterV defines franchised distributors through particular product/distribution activities and an in-state place of business. Products are tangible items for this chapter. A business-to-business service licence is not automatically covered merely because it uses the word franchise, and a product distributor should not assume the chapter is irrelevant because its contract uses another label.'),
sec('For covered relationships, read more than the exit clause','The statute addresses unjust termination/nonrenewal, good cause and bad faith and states an at-least90-day notice rule. The management team must establish coverage and relevant facts before applying those provisions. A contractual permission to terminate without specifying grounds is not, by itself, the complete legal answer.'),
sec('Fictional example: an Italian equipment brand','A Delaware distributor buys branded equipment for resale through retail outlets. Before replacing it with another distributor, the sales director records the product flow, locations, brands, agreement dates and alleged defaults. The team separates the commercial preference for a new partner from the legal basis and procedure for ending the existing relationship.'),
sec('Do not overread the worker clause','Section2554also contains worker-classification language limited to purposes of Title19Chapter11. It should not be described as immunity from all employment, tax or joint-employer rules. The operator’s employees, the operator entity and the brand’s staff remain separate roles.'),
sec('Prepare an exit fact pack',bullets=['Distribution activities and actual in-state place of business.','Product and trademark flow, current agreement and amendments.','Specific reasons, evidence and proposed timing.','Independent notice, remedies, workforce and inventory review.'])], 'A Delaware distributor scope and exit-review packet.',topic='relationship')
guide('Florida','Florida: the annual franchise exemption filing still comes first','The agency removed registration-document requirements while retaining the annual franchise exemption notice.',['fl-annual-notice'],[
sec('Do not stop at the first agency sentence','FDACS says sellers of business franchises no longer file registration documents. Its next sentence says the Franchise Exemption filing remains. Current2026section559.802conditions the exemption on a qualifying federal-definition franchise, the notice stating substantialFTCcompliance and payment of the set fee before the covered offer or sale.'),
sec('Check both location and resident connections','The statute addresses a franchise to be located in Florida or a Florida resident. A prospect outside the proposed outlet state can therefore still be relevant. The notice is not replaced by forming a U.S. company, drafting an FDD or choosing a licence label.'),
sec('Filing and renewal have their own dates','The statute gives the initial exemption one year from notice filing and allows annual renewal. It sets a fee ceiling of$100; that ceiling is not evidence of the current amount payable. The linked application packet required sign-in during this research, so the actual current filing fee and packet instructions remain a pre-filing confirmation task.'),
sec('Fictional example: a German service brand','A Florida-resident partner proposes an operation elsewhere. The expansion manager records the resident and outlet facts separately, checks the applicable exemption and calendars the notice before a covered offer. The company secretary also records the anniversary, selling entity andFDDversion.'),
sec('Evidence to retain',bullets=['Federal-definition/compliance analysis for the actual model.','Prospect residence and proposed outlet location.','Current agency form, actual fee and notice receipt.','One-year anniversary and renewal owner.','Independent advertising, sector and relationship-law questions.'])], 'A Florida pre-offer notice and annual-renewal record.')
guide('Georgia','Georgia: keep trade names and brand rights in separate records','A business-name record and a goods-or-services mark answer different questions; preserve the actual source version for any exemption analysis.',['ga-name-mark','ga-source-version'],[
sec('Name the evidence precisely','Georgia’s Secretary of State distinguishes a trade name used to identify the business from a trademark or service mark identifying goods or services. A company-name orDBArecord is therefore not, by itself, the brand-rights evidence a group needs for a licensing chain. Record the exact kind of mark and the legal entity holding each right.'),
sec('The legal-source date matters','The Attorney General hosts a business-opportunity statutory text expressly labelled current through the2006Regular Session. Reading that page today establishes its wording and date, not that every threshold or exclusion remains current. This site has not used its dated numerical requirements as a current Georgia sales-law clearance.'),
sec('Fictional example: a Singapore training group','The parent’s company name, the trading name used by aU.S.seller and the service mark on training materials differ. The company secretary builds one row for each asset and licence rather than filing them all under “brand registered.” A reviewer can then test the actual current state and federal rules against the right evidence.'),
sec('Prepare a rights-and-source ledger',table={'headers':['Record','Facts to capture'],'rows':[['Business or trade name','Entity using it, recording authority and location'],['Trademark/service mark','Owner, jurisdiction, registration/application and goods/services'],['Group licence','Grantor, licensee, territory and sublicensing rights'],['Legal claim or exclusion','Current statutory provision, source version and applicability reviewer']]}),
sec('The next legal research task','Current business-opportunity applicability, any filing, disclosure, advertising and relationship overlays remain unresolved in the matrix. The ledger is useful preparation, and completing it does not establish an exemption or complete brand clearance.')], 'A Georgia business-name, mark-rights and source-version ledger.',topic='ip-data')
guide('Idaho','Idaho: registration is not a licence or a complete operating checklist','Use the actual service and address to separate entity, occupational, tax and local requirements.',['id-operating-records','id-representations'],[
sec('Use the official portal’s distinction narrowly','Business.Idaho.gov says business registration is a registration, not a licence, and distinguishes it from occupational requirements, tax accounts and city/county rules. Its statement that Idaho lacks a general state business licence does not establish absence of franchise-sales or sector duties.'),
sec('An absent activity is not proof of no requirement','The page says its licensing information is not guaranteed complete and directs users to verify particular activities with appropriate agencies. A cleaning service that adds pesticide application, electrical work or a specialised technical service needs a fresh activity analysis. This page does not determine which professional category the business falls into.'),
sec('Fictional example: commercial cleaning with an add-on','A European brand begins with routine cleaning but proposes to sell disinfection treatments and specialist maintenance through its operator. TheCOO lists each service actually offered, who performs it and the equipment or substances used. The operator then identifies state and local authorities for those activities before accepting customer work.'),
sec('Give every requirement an owner',bullets=['Operating entity and name registration: company secretary.','Individual/firm occupational rules: operations lead.','Tax/employer accounts: finance andHR.','Actual municipal/county address and permits: local manager.','Partner advertising and substantiation: sales compliance owner.']),
sec('Keep the franchise workstream visible','The Attorney General’s general consumer-law guidance is a separate reason to review accurate cost, support and earnings representations. The state-specific franchise filing/exemption analysis remains unresolved here; no missing entry is treated as permission to sell.')], 'An Idaho activity-by-authority operating checklist with the franchise research question kept separate.',topic='premises-opening')
guide('Iowa','Iowa: separate disclosure exemptions, filing and relationship protections','A Chapter551Adisclosure exemption is not the same as the registered-mark exclusion or the current relationship regime.',['ia-business-opportunity','ia-current-relationship','ia-future-review'],[
sec('Choose the precise business-opportunity route','Current2026Chapter551Adistinguishes the definition/exclusions in551A.1from the disclosure exemption in551A.4. The franchise disclosure route applies to section551A.3and requires the specified document at the earlier first personal meeting or fourteen days before the stated commitment/payment event. Section551A.7has its own consent-to-service filing before contract or sale. Do not assume an exemption only from551A.3removes that distinct task.'),
sec('Use the correct relationship law for the agreement date','Chapter523Hcontains an explicit limit for agreements entered on or afterJuly1,2000. Current537A.10addresses defined Iowa-operated franchises with agreements from that date, subject to location and sector exclusions. Its protections include transfer, encroachment and termination issues; the commercial label does not choose the regime.'),
sec('Fictional example: an Irish facilities network','The brand plans a partner meeting, several service territories and a later master arrangement. The company secretary identifies the selected Chapter551Aroute and first-meeting event; theCOO records the operator office, agreement date, territory and customer allocation. Those facts support two separate reviews rather than one “Iowa exempt” box.'),
sec('Future legislation is a review task','Iowa’s official2026amendment table flags a signed amendment to537A.10(7)(c)(2)effectiveJanuary1,2027. The current date isNovember12,2026. Keep that upcoming change in the review queue instead of applying its future text today.'),
sec('Output for the management team',bullets=['Definition/exclusion or disclosure-exemption route with exact scope.','Meeting, disclosure, consent and commitment dates.','Agreement date and actual Iowa premises/principal-office facts.','Territory/transfer/exit questions for the correct relationship regime.','A scheduled editorial review of the2027change.'])], 'An Iowa two-track applicability memo with a future-law review flag.')
guide('Kansas','Kansas: foreign qualification is an activity decision, not an entry model','Identify which non-Kansas entity will operate in Kansas before assigning resident-agent and registration work.',['ks-foreign-qualification'],[
sec('Start with the operating entity and activity','Kansas Secretary of State says non-Kansas businesses doing business in Kansas must register and provides foreign-entity application forms. “Foreign” in this context means formed outside Kansas, including anotherU.S.state; it is not a decision about immigration nationality or tax residence. Determine actual activities and applicable exceptions before filing.'),
sec('The registered office has a different purpose','Kansas One Stop explains that the resident agent receives legal process and that the registered office is the physical Kansas address where the agent can be reached. Keep that address distinct from the overseas parent’s headquarters, customer location and franchise outlet. The domestic-oriented checklist is not evidence that the parent must move its headquarters to Kansas.'),
sec('Fictional example: a Dutch technical-services parent','A locally owned partner will contract with customers while the parent supplies brand rights and remote support. The company secretary lists each entity’s actual Kansas activities, staff visits, contract roles and office arrangements. The team then decides which entity needs a qualification analysis. It does not automatically form another subsidiary merely to complete a checklist.'),
sec('Prepare one row per entity',table={'headers':['Field','What to record'],'rows':[['Identity','Legal name, formation jurisdiction and group role'],['Activities','Who contracts, invoices, employs and performs work'],['Kansas connections','Office, personnel, contracts and actual service location'],['Process contact','Resident agent and physical registered office if required'],['Separate reviews','Tax nexus, franchise sales, people mobility and sector rules']]}),
sec('Coverage limit','This page does not resolve Kansas franchise-registration, exemption, disclosure, advertising or relationship duties. Those remain explicit unresolved dimensions. Entity registration and a service-of-process address do not approve an offer of business rights.')], 'A Kansas entity-activity and foreign-qualification worksheet.',topic='corporate-tax')
guide('Kentucky','Kentucky: update the franchise exemption process for the 2026 rule','The current rule uses an exemption-notice portal and preserves a fourteen-day material-change task.',['ky-franchise-notice','ky-material-changes','ky-nonexempt'],[
sec('The exemption has evidence conditions','KRS367.807(1)(a)requires the federal franchise definition/compliance and written notice for the described exemption. Current40KAR12:410, effectiveJune30,2026, directs notice through the Franchise Exemption Notice portal and asks for authority-to-transact evidence and theFDDfor this route. A foreign parent’s operating history does not by itself establish the proposed seller’s authority or compliance.'),
sec('Read the current version of the rule','The official page contains current text as well as older/redline material. Its operative sections describe separate registration, renewal and exempt-offeror processes. A manager should use the current section3for the franchise notice, rather than automatically attaching the older business-opportunity determination forms.'),
sec('The filing does not end the task','Current section4requires written notification within fourteen days of a material change to information supplied by a registered seller or an offeror submitting an exemption notice. Keep the original submission and an accountable owner for changes. The non-exempt business-opportunity registration track has its own approval, fees and annual period; it is not interchangeable with the exemption route.'),
sec('Fictional example: a Spanish training brand','The group changes its selling subsidiary’s principal details after submitting the notice. The company secretary compares the new facts with the submitted information, assigns the material-change review and preserves the notification. The sales team also checks the correctFDDversion before using it.'),
sec('Practical record',bullets=['Exact exemption provision and federal compliance evidence.','Actual offeror and authority-to-transact document.','CurrentFDDand submitted portal record.','Fourteen-day material-change owner and event log.','Independent advertising, professional-sector and relationship-law questions.'])], 'A current Kentucky exemption evidence pack and event-driven change log.')
guide('Louisiana','Louisiana: the trademark wording does not settle every opportunity trigger','Location, buyback and earnings promises can require a separate screen; bond duties have their own limited scope.',['la-definition','la-bonds','la-claims','la-real-estate'],[
sec('Read the whole definition','RS51:1821contains registered-mark wording within a particular sales/marketing-plan provision. It separately describes location assistance, buyback and earnings/refund representations. The registered-mark phrase should not be converted into a universal exemption from every business-opportunity trigger.'),
sec('The bond rule has its own boundary','RS51:1822specifies distinct seller and agent bonds and requires covered bonds before business, including advertising or soliciting. Its subsectionGlimits those requirements to opportunities defined in51:1821(1)(a),(b)or(c). That boundary matters: a rule for one kind of offer is not a blanket bond requirement for every licensing model.'),
sec('Fictional example: a German equipment-service package','The seller licences a registered mark, supplies equipment and promises to buy back output if the operator is dissatisfied. The manager records each promise separately instead of stopping at the mark. The reviewer tests each statutory trigger and any resulting seller/agent role. Sales operations retains substantiation and puts the actual promises into the written contract where required.'),
sec('A regulated sector can add an earlier task','RS37:1465separately requires the described franchisor dealing with a Louisiana real-estate broker to appoint a Louisiana-licensed broker representative before entering that franchise agreement. This is a specific professional-sector rule, not an assumption that every property-related service is a real-estate brokerage.'),
sec('Prepare before promotion',bullets=['Goods/services, payments and every location, income, refund or buyback promise.','Exact definition limb and bond applicability, including agent role.','Earnings support and actual seller identification in covered advertising.','Service-of-process appointment and written promises.','Professional-sector review for the actual activity.'])], 'A Louisiana trigger-by-trigger sales-model screen with independent bond and sector tasks.')
guide('Maine','Maine: the first sales meeting can matter before the contract date','Covered business opportunities have separate promotion, disclosure, security and avoidance tasks; the mark exception is limited.',['me-opportunities','me-contract-cancellation'],[
sec('Classify the actual promise','Maine’s current Title32Chapter69-B describes business-opportunity triggers, including particular location, buyback, earnings/refund and marketing assistance. The federally registered-mark wording qualifies the marketing-program limb. It does not, by itself, erase every other trigger. The officialPDF states currency throughOctober1,2026 and that it is not the certified annotated text.'),
sec('Do not calendar only payment','For a covered opportunity,4696requires registration before selling, offering, advertising or promotion. Section4692places disclosure at the earliest specified72-hour preagreement/prepayment event or the first face-to-face sales meeting. The meeting is therefore a real dependency to check rather than an assumed unrestricted discovery event.'),
sec('Fictional example: a Finnish specialist-service system','The brand plans an in-person pitch and equipment package. Its coordinator collects the proposed advertisement, meeting purpose, assistance promises, payments and agreement. The responsible reviewer establishes coverage and each early event before the team commits funds or tells a prospect that the registered mark settles state treatment.'),
sec('Include the post-signature work','For a covered opportunity,4698provides a three-full-business-day avoidance process with return obligations. The chapter also addresses financial security, annual registration and exceptions. Those events are distinct from federal franchise disclosure and from operational permits.'),
sec('Build a dependency record',bullets=['Actual statutory trigger and any exclusion, with evidence.','Promotion, first face-to-face meeting, signature and payment dates.','Disclosure version, registration and any applicable financial security.','Avoidance notice/return procedure and responsible person.','Current forms, certified text and case-specific interpretation for review.'])], 'A Maine promotion-to-contract timeline with the first meeting and avoidance process visible.')
guide('Massachusetts','Massachusetts: map service work before assuming contractor status','The statutory services threshold and three independent-contractor conditions require actual facts, not only a contract label.',['ma-services'],[
sec('Start with who performs services for whom','General Laws149section148Bbegins with an individual performing services. Its exception requires all three stated conditions: freedom from control and direction in the contract and in fact; service outside the employer’s usual course; and an independently established business of the same nature. Applying that framework needs the actual services relationship and relevant current case law.'),
sec('Separate the people and entities','A brand owner, partner company, individual owner-manager, employed supervisor and field technician are different roles. The word franchise does not automatically determine each person’s employment status; equally, the statute is not a rule that every franchisee is an employee. Management independence at the overseas parent does not answer theU.S.workforce question.'),
sec('Fictional example: a French maintenance brand','The partner’s owner wins accounts, individual technicians perform service visits and the brand’s remote team audits quality. TheCOOrecords who sets schedules, prices work, recruits people, supplies tools, supervises performance and pays each person. The reviewer first identifies the relevant service and alleged employer, then examines the statutory conditions and case law.'),
sec('Create an operating responsibility map',bullets=['Every entity/person and the service actually provided.','Customer contract, invoice, payroll and supervision flows.','Contractual controls compared with day-to-day practice.','Independent-business evidence where relevant.','Named employment reviewer and unresolved threshold/application questions.']),
sec('Keep employer readiness separate','Once the responsible employer is established, hiring, wages, leave, insurance and safety become separate workstreams. Completing this fact map establishes neither worker classification nor a franchise-sales exemption.')], 'A Massachusetts service-and-employer responsibility map for an evidence-based classification review.',topic='employment')
