# Human text normalization only; IDs, source passages, URLs and provenance remain literal.
def human(s):
 s=re.sub(r'(?<=[A-Za-z])(?=\d)', ' ',s)
 s=re.sub(r'(?<=\d)(?=(?:days|day|years|year|months|hours|hour|calendar|business|of|and|as|notice|was|states|Chapter|Title))',' ',s)
 s=re.sub(r',(?=\d{4}(?:\D|$))',', ',s)
 for a,b in {'FTCcompliance':'FTC compliance','FTCcompliant':'FTC compliant','substantialFTC':'substantial FTC','FTCdefinition':'FTC definition','theFDD':'the FDD','currentFDD':'current FDD','seller’sFDD':'seller’s FDD','U.S.brand':'U.S. brand','U.S.workforce':'U.S. workforce','U.S.state':'U.S. state','aU.S.seller':'a U.S. seller','theCOO':'the COO','andHR':'and HR','FDACSdistinguishes':'FDACS distinguishes','currentonlythrough':'current only through','post-signature':'post-signature','16CFR':'16 CFR','40KAR':'40 KAR','KRS367':'KRS 367','RS51':'RS 51','RS37':'RS 37','ARS44':'ARS 44','FDDversion':'FDD version','FDDdelivery':'FDD delivery','FDDregistration':'FDD registration'}.items():s=s.replace(a,b)
 return s
